/**
 * Minimal promise wrapper over IndexedDB. All data stays on the device; the
 * app has no backend and never transmits facial data.
 */
const DB_NAME = 'facial-palsy-companion';
const DB_VERSION = 4;

export type StoreName = 'kv' | 'sessions' | 'ratings' | 'rehab' | 'photos' | 'synk' | 'snapshots';

let dbPromise: Promise<IDBDatabase> | null = null;

function open(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains('kv')) db.createObjectStore('kv');
      if (!db.objectStoreNames.contains('sessions')) db.createObjectStore('sessions', { keyPath: 'id' });
      if (!db.objectStoreNames.contains('ratings')) {
        db.createObjectStore('ratings', { keyPath: 'id' }).createIndex('sessionId', 'sessionId');
      }
      if (!db.objectStoreNames.contains('rehab')) db.createObjectStore('rehab', { keyPath: 'id' }).createIndex('date', 'date');
      // v2: single-photo analysis records
      if (!db.objectStoreNames.contains('photos')) db.createObjectStore('photos', { keyPath: 'id' }).createIndex('caseId', 'caseId');
      // v3: synkinesis finder records
      if (!db.objectStoreNames.contains('synk')) db.createObjectStore('synk', { keyPath: 'id' });
      // v4: optional assessment photos (one per step, keyed by session id; off unless the user turns it on)
      if (!db.objectStoreNames.contains('snapshots')) db.createObjectStore('snapshots', { keyPath: 'id' });
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  return dbPromise;
}

function run<T>(store: StoreName, mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return open().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const tx = db.transaction(store, mode);
        const req = fn(tx.objectStore(store));
        tx.oncomplete = () => resolve(req.result);
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error);
      }),
  );
}

export const db = {
  getAll: <T>(store: Exclude<StoreName, 'kv'>) => run<T[]>(store, 'readonly', (s) => s.getAll() as IDBRequest<T[]>),
  put: <T>(store: Exclude<StoreName, 'kv'>, value: T) => run(store, 'readwrite', (s) => s.put(value)),
  /** Insert-only: fails if the key already exists (assessment records are immutable). */
  add: <T>(store: Exclude<StoreName, 'kv'>, value: T) => run(store, 'readwrite', (s) => s.add(value)),
  delete: (store: Exclude<StoreName, 'kv'>, key: string) => run(store, 'readwrite', (s) => s.delete(key)),
  get: <T>(store: Exclude<StoreName, 'kv'>, key: string) => run<T | undefined>(store, 'readonly', (s) => s.get(key) as IDBRequest<T | undefined>),
  count: (store: Exclude<StoreName, 'kv'>) => run<number>(store, 'readonly', (s) => s.count()),
  clear: (store: Exclude<StoreName, 'kv'>) => run(store, 'readwrite', (s) => s.clear()),
  getKv: <T>(key: string) => run<T | undefined>('kv', 'readonly', (s) => s.get(key) as IDBRequest<T | undefined>),
  setKv: <T>(key: string, value: T) => run('kv', 'readwrite', (s) => s.put(value, key)),
  async clearAll(): Promise<void> {
    for (const s of ['kv', 'sessions', 'ratings', 'rehab', 'photos', 'synk', 'snapshots'] as const) await run(s, 'readwrite', (st) => st.clear());
  },
};

export const uid = (): string =>
  typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;

/** Local calendar date YYYY-MM-DD. */
export function localDate(d: Date = new Date()): string {
  const z = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${z(d.getMonth() + 1)}-${z(d.getDate())}`;
}

export function daysBetween(fromYmd: string, to: Date = new Date()): number {
  const [y, m, d] = fromYmd.split('-').map(Number) as [number, number, number];
  const a = Date.UTC(y, m - 1, d);
  const b = Date.UTC(to.getFullYear(), to.getMonth(), to.getDate());
  return Math.round((b - a) / 86_400_000);
}
